ALTER TABLE public.properties ADD COLUMN state text;
ALTER TABLE public.tenancies ADD COLUMN end_date date, ADD COLUMN payment_day integer NOT NULL DEFAULT 1 CHECK(payment_day BETWEEN 1 AND 28), ADD COLUMN grace_days integer NOT NULL DEFAULT 0 CHECK(grace_days BETWEEN 0 AND 30), ADD COLUMN deposit_amount numeric NOT NULL DEFAULT 0 CHECK(deposit_amount >= 0), ADD COLUMN annual_increase numeric CHECK(annual_increase BETWEEN 0 AND 100), ADD COLUMN deposit_status text NOT NULL DEFAULT 'held' CHECK(deposit_status IN ('held','returned','partial'));
ALTER TABLE public.invitations ADD COLUMN start_date date NOT NULL DEFAULT CURRENT_DATE, ADD COLUMN end_date date, ADD COLUMN payment_day integer NOT NULL DEFAULT 1 CHECK(payment_day BETWEEN 1 AND 28), ADD COLUMN grace_days integer NOT NULL DEFAULT 0 CHECK(grace_days BETWEEN 0 AND 30), ADD COLUMN deposit_amount numeric NOT NULL DEFAULT 0 CHECK(deposit_amount >= 0), ADD COLUMN annual_increase numeric CHECK(annual_increase BETWEEN 0 AND 100);
CREATE FUNCTION public.contract_party(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.tenancies WHERE id=_id AND (landlord_id=auth.uid() OR tenant_id=auth.uid())); $$;
CREATE FUNCTION public.contract_owner(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.tenancies WHERE id=_id AND landlord_id=auth.uid()); $$;
CREATE TABLE public.rent_charges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenancy_id uuid NOT NULL REFERENCES public.tenancies(id), period date NOT NULL, due_on date NOT NULL, amount numeric NOT NULL CHECK(amount>=0), credit_applied numeric NOT NULL DEFAULT 0 CHECK(credit_applied>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenancy_id,period));
GRANT SELECT ON public.rent_charges TO authenticated; GRANT ALL ON public.rent_charges TO service_role;
ALTER TABLE public.rent_charges ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Contract charges" ON public.rent_charges FOR SELECT TO authenticated USING(public.contract_party(tenancy_id));
ALTER TABLE public.payments ADD COLUMN charge_id uuid REFERENCES public.rent_charges(id), ADD COLUMN confirmation_status text NOT NULL DEFAULT 'confirmed' CHECK(confirmation_status IN ('pending','confirmed','rejected')), ADD COLUMN proof_path text, ADD COLUMN review_note text, ADD COLUMN receipt_number bigint GENERATED BY DEFAULT AS IDENTITY;
CREATE TABLE public.rental_expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenancy_id uuid NOT NULL REFERENCES public.tenancies(id), property_id uuid NOT NULL REFERENCES public.properties(id), category text NOT NULL CHECK(length(category)<=100), amount numeric NOT NULL CHECK(amount>0), paid_on date NOT NULL DEFAULT CURRENT_DATE, note text CHECK(length(note)<=2000), payer text NOT NULL CHECK(payer IN ('landlord','tenant')), reimbursement text NOT NULL DEFAULT 'none' CHECK(reimbursement IN ('none','rent_credit')), unapplied_credit numeric NOT NULL DEFAULT 0, issue_id uuid UNIQUE REFERENCES public.issues(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.rental_expenses TO authenticated; GRANT ALL ON public.rental_expenses TO service_role;
ALTER TABLE public.rental_expenses ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read contract expenses" ON public.rental_expenses FOR SELECT TO authenticated USING(public.contract_party(tenancy_id));
CREATE POLICY "Owner records expenses" ON public.rental_expenses FOR INSERT TO authenticated WITH CHECK(public.contract_owner(tenancy_id) AND EXISTS(SELECT 1 FROM public.tenancies t WHERE t.id=tenancy_id AND t.property_id=rental_expenses.property_id));
CREATE TABLE public.credit_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), expense_id uuid NOT NULL REFERENCES public.rental_expenses(id), charge_id uuid NOT NULL REFERENCES public.rent_charges(id), amount numeric NOT NULL CHECK(amount>0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.credit_allocations TO authenticated; GRANT ALL ON public.credit_allocations TO service_role;
ALTER TABLE public.credit_allocations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own credits" ON public.credit_allocations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.rent_charges c WHERE c.id=charge_id AND public.contract_party(c.tenancy_id)));
CREATE TABLE public.contract_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenancy_id uuid NOT NULL REFERENCES public.tenancies(id), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 255), category text NOT NULL DEFAULT 'other', path text NOT NULL UNIQUE, shared boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.contract_documents TO authenticated; GRANT ALL ON public.contract_documents TO service_role;
ALTER TABLE public.contract_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read visible documents" ON public.contract_documents FOR SELECT TO authenticated USING(public.contract_owner(tenancy_id) OR (shared AND public.contract_party(tenancy_id)));
CREATE POLICY "Owner adds documents" ON public.contract_documents FOR INSERT TO authenticated WITH CHECK(public.contract_owner(tenancy_id) AND split_part(path,'/',1)=tenancy_id::text);
CREATE POLICY "Owner edits documents" ON public.contract_documents FOR UPDATE TO authenticated USING(public.contract_owner(tenancy_id)) WITH CHECK(public.contract_owner(tenancy_id));
CREATE POLICY "Owner removes documents" ON public.contract_documents FOR DELETE TO authenticated USING(public.contract_owner(tenancy_id));
CREATE TABLE public.inventories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenancy_id uuid NOT NULL REFERENCES public.tenancies(id), phase text NOT NULL CHECK(phase IN ('entry','exit')), area text NOT NULL CHECK(length(area) BETWEEN 1 AND 100), condition text NOT NULL CHECK(condition IN ('good','fair','damaged')), note text CHECK(length(note)<=2000), photo_path text, agreed_by uuid, agreed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenancy_id,phase,area));
GRANT SELECT,INSERT,UPDATE ON public.inventories TO authenticated; GRANT ALL ON public.inventories TO service_role;
ALTER TABLE public.inventories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Parties read inventory" ON public.inventories FOR SELECT TO authenticated USING(public.contract_party(tenancy_id));
CREATE POLICY "Owner creates inventory" ON public.inventories FOR INSERT TO authenticated WITH CHECK(public.contract_owner(tenancy_id));
CREATE POLICY "Owner edits unaccepted inventory" ON public.inventories FOR UPDATE TO authenticated USING(public.contract_owner(tenancy_id) AND agreed_at IS NULL) WITH CHECK(public.contract_owner(tenancy_id) AND agreed_at IS NULL);
CREATE FUNCTION public.agree_inventory(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.inventories i SET agreed_by=auth.uid(),agreed_at=now() WHERE i.id=_id AND i.agreed_at IS NULL AND EXISTS(SELECT 1 FROM public.tenancies t WHERE t.id=i.tenancy_id AND t.tenant_id=auth.uid()); IF NOT FOUND THEN RAISE EXCEPTION 'Inventario no disponible'; END IF; END; $$;
CREATE TABLE public.deposit_deductions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenancy_id uuid NOT NULL REFERENCES public.tenancies(id), amount numeric NOT NULL CHECK(amount>0), reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.deposit_deductions TO authenticated; GRANT ALL ON public.deposit_deductions TO service_role;
ALTER TABLE public.deposit_deductions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read deductions" ON public.deposit_deductions FOR SELECT TO authenticated USING(public.contract_party(tenancy_id));
CREATE POLICY "Record deductions" ON public.deposit_deductions FOR INSERT TO authenticated WITH CHECK(public.contract_owner(tenancy_id));
CREATE POLICY "Remove deductions" ON public.deposit_deductions FOR DELETE TO authenticated USING(public.contract_owner(tenancy_id));
CREATE TABLE public.activity_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenancy_id uuid NOT NULL REFERENCES public.tenancies(id), event text NOT NULL, reference_id uuid, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity_log TO authenticated; GRANT ALL ON public.activity_log TO service_role;
ALTER TABLE public.activity_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read contract activity" ON public.activity_log FOR SELECT TO authenticated USING(public.contract_party(tenancy_id));
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL, path text NOT NULL, reference_id uuid, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own notifications" ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "Mark own notifications" ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.notification_preferences(user_id uuid PRIMARY KEY, payment_reminders boolean NOT NULL DEFAULT true, proof_alerts boolean NOT NULL DEFAULT true, repair_alerts boolean NOT NULL DEFAULT true, message_alerts boolean NOT NULL DEFAULT true, weekly_summary boolean NOT NULL DEFAULT true, contract_alerts boolean NOT NULL DEFAULT true, advance_days integer NOT NULL DEFAULT 3 CHECK(advance_days BETWEEN 1 AND 30), reminder_text text NOT NULL DEFAULT 'Hola {nombre}, tu renta de {monto} vence el {fecha}.' CHECK(length(reminder_text)<=2000));
GRANT SELECT,INSERT,UPDATE ON public.notification_preferences TO authenticated; GRANT ALL ON public.notification_preferences TO service_role;
ALTER TABLE public.notification_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read preferences" ON public.notification_preferences FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "Create preferences" ON public.notification_preferences FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY "Edit preferences" ON public.notification_preferences FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.legal_notices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), landlord_id uuid NOT NULL, state text NOT NULL, content text NOT NULL CHECK(length(content)<=4000), UNIQUE(landlord_id,state));
GRANT SELECT,INSERT,UPDATE ON public.legal_notices TO authenticated; GRANT ALL ON public.legal_notices TO service_role;
ALTER TABLE public.legal_notices ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own notices" ON public.legal_notices FOR SELECT TO authenticated USING(landlord_id=auth.uid());
CREATE POLICY "Add own notices" ON public.legal_notices FOR INSERT TO authenticated WITH CHECK(landlord_id=auth.uid());
CREATE POLICY "Edit own notices" ON public.legal_notices FOR UPDATE TO authenticated USING(landlord_id=auth.uid()) WITH CHECK(landlord_id=auth.uid());
ALTER TABLE public.messages ADD COLUMN tenancy_id uuid REFERENCES public.tenancies(id);
UPDATE public.messages m SET tenancy_id=(SELECT t.id FROM public.tenancies t WHERE (t.landlord_id=m.sender_id AND t.tenant_id=m.recipient_id) OR (t.tenant_id=m.sender_id AND t.landlord_id=m.recipient_id) ORDER BY t.created_at LIMIT 1);
CREATE POLICY "Messages require matching contract" ON public.messages AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(length(content) BETWEEN 1 AND 4000 AND EXISTS(SELECT 1 FROM public.tenancies t WHERE t.id=tenancy_id AND t.status='active' AND ((t.landlord_id=sender_id AND t.tenant_id=recipient_id) OR (t.tenant_id=sender_id AND t.landlord_id=recipient_id))));
ALTER TABLE public.issues ADD COLUMN tenancy_id uuid REFERENCES public.tenancies(id), ADD COLUMN estimated_cost numeric CHECK(estimated_cost>=0), ADD COLUMN actual_cost numeric CHECK(actual_cost>=0), ADD COLUMN provider_name text CHECK(length(provider_name)<=200), ADD COLUMN provider_phone text CHECK(length(provider_phone)<=40), ADD COLUMN payer text NOT NULL DEFAULT 'landlord' CHECK(payer IN ('landlord','tenant','tenant_credit')), ADD COLUMN media_paths text[] NOT NULL DEFAULT '{}';
UPDATE public.issues i SET tenancy_id=(SELECT t.id FROM public.tenancies t WHERE t.property_id=i.property_id AND t.tenant_id=i.tenant_id ORDER BY t.created_at LIMIT 1);
CREATE POLICY "Reports match contract" ON public.issues AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.contract_party(tenancy_id) AND EXISTS(SELECT 1 FROM public.tenancies t WHERE t.id=tenancy_id AND t.property_id=issues.property_id AND t.tenant_id=auth.uid() AND t.landlord_id=issues.landlord_id) AND length(title) BETWEEN 1 AND 200 AND length(coalesce(description,''))<=4000 AND cardinality(media_paths)<=5);
CREATE TABLE public.issue_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), issue_id uuid NOT NULL REFERENCES public.issues(id), author_id uuid NOT NULL, content text NOT NULL CHECK(length(content) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.issue_comments TO authenticated; GRANT ALL ON public.issue_comments TO service_role;
ALTER TABLE public.issue_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Parties read repair comments" ON public.issue_comments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.issues i WHERE i.id=issue_id AND (i.landlord_id=auth.uid() OR i.tenant_id=auth.uid())));
CREATE POLICY "Parties comment repairs" ON public.issue_comments FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND EXISTS(SELECT 1 FROM public.issues i WHERE i.id=issue_id AND (i.landlord_id=auth.uid() OR i.tenant_id=auth.uid())));
CREATE FUNCTION public.generate_rent_charges(_tenancy uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.tenancies; m date; d date; BEGIN SELECT * INTO t FROM public.tenancies WHERE id=_tenancy; IF NOT FOUND OR (auth.uid() IS NOT NULL AND NOT public.contract_party(_tenancy)) THEN RAISE EXCEPTION 'Contrato no disponible'; END IF; IF t.status NOT IN ('active','expiring') THEN RETURN; END IF; FOR m IN SELECT generate_series(date_trunc('month',t.start_date),date_trunc('month',least(coalesce(t.end_date,(CURRENT_DATE+interval '11 months')::date),(CURRENT_DATE+interval '11 months')::date)),interval '1 month')::date LOOP d:=m+(t.payment_day-1); IF d>=t.start_date AND (t.end_date IS NULL OR d<=t.end_date) THEN INSERT INTO public.rent_charges(tenancy_id,period,due_on,amount) VALUES(t.id,m,d,t.rent_amount) ON CONFLICT DO NOTHING; END IF; END LOOP; END; $$;
CREATE FUNCTION public.apply_rent_credits(_tenancy uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.rental_expenses; c record; a numeric; BEGIN IF auth.uid() IS NOT NULL AND NOT public.contract_owner(_tenancy) THEN RAISE EXCEPTION 'Sin permiso'; END IF; PERFORM 1 FROM public.tenancies WHERE id=_tenancy FOR UPDATE; FOR e IN SELECT * FROM public.rental_expenses WHERE tenancy_id=_tenancy AND unapplied_credit>0 ORDER BY created_at FOR UPDATE LOOP FOR c IN SELECT r.*,r.amount-r.credit_applied-coalesce((SELECT sum(p.amount) FROM public.payments p WHERE p.charge_id=r.id AND p.confirmation_status='confirmed'),0) AS remaining FROM public.rent_charges r WHERE r.tenancy_id=_tenancy ORDER BY due_on FOR UPDATE LOOP a:=least(e.unapplied_credit,greatest(c.remaining,0)); IF a>0 THEN UPDATE public.rent_charges SET credit_applied=credit_applied+a WHERE id=c.id; INSERT INTO public.credit_allocations(expense_id,charge_id,amount) VALUES(e.id,c.id,a); e.unapplied_credit:=e.unapplied_credit-a; END IF; EXIT WHEN e.unapplied_credit<=0; END LOOP; UPDATE public.rental_expenses SET unapplied_credit=e.unapplied_credit WHERE id=e.id; END LOOP; END; $$;
CREATE FUNCTION public.expense_credit_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.unapplied_credit:=CASE WHEN NEW.payer='tenant' AND NEW.reimbursement='rent_credit' THEN NEW.amount ELSE 0 END; RETURN NEW; END; $$;
CREATE TRIGGER expense_credit_before BEFORE INSERT ON public.rental_expenses FOR EACH ROW EXECUTE FUNCTION public.expense_credit_trigger();
CREATE FUNCTION public.expense_apply_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.apply_rent_credits(NEW.tenancy_id); RETURN NEW; END; $$;
CREATE TRIGGER expense_credit_after AFTER INSERT ON public.rental_expenses FOR EACH ROW EXECUTE FUNCTION public.expense_apply_trigger();
CREATE FUNCTION public.contract_charges_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.end_date IS NOT NULL AND NEW.end_date<NEW.start_date THEN RAISE EXCEPTION 'Fin anterior al inicio'; END IF; PERFORM public.generate_rent_charges(NEW.id); RETURN NEW; END; $$;
CREATE TRIGGER contract_charges AFTER INSERT OR UPDATE OF start_date,end_date,payment_day,rent_amount ON public.tenancies FOR EACH ROW EXECUTE FUNCTION public.contract_charges_trigger();
CREATE OR REPLACE FUNCTION public.accept_invitation(_code text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.invitations; u uuid:=auth.uid(); BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Debes iniciar sesión'; END IF; SELECT * INTO i FROM public.invitations WHERE code=_code FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Invitación no encontrada'; END IF; IF i.landlord_id=u THEN RAISE EXCEPTION 'No puedes aceptar tu propia invitación'; END IF; IF lower(i.tenant_email)<>lower(coalesce(auth.jwt()->>'email','')) THEN RAISE EXCEPTION 'Inicia sesión con el correo invitado'; END IF; IF i.status='accepted' THEN IF i.accepted_by=u THEN RETURN i.property_id; ELSE RAISE EXCEPTION 'Invitación ya utilizada'; END IF; END IF; IF EXISTS(SELECT 1 FROM public.tenancies WHERE property_id=i.property_id AND status IN ('active','expiring')) THEN RAISE EXCEPTION 'La propiedad ya tiene un contrato activo'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(u,'tenant') ON CONFLICT DO NOTHING; INSERT INTO public.tenancies(property_id,landlord_id,tenant_id,rent_amount,start_date,end_date,payment_day,grace_days,deposit_amount,annual_increase) VALUES(i.property_id,i.landlord_id,u,i.rent_amount,i.start_date,i.end_date,i.payment_day,i.grace_days,i.deposit_amount,i.annual_increase); UPDATE public.invitations SET status='accepted',accepted_by=u,accepted_at=now() WHERE id=i.id; RETURN i.property_id; END; $$;
CREATE FUNCTION public.record_charge_payment(_charge uuid,_amount numeric,_method text,_paid_on date,_note text DEFAULT NULL,_proof text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.rent_charges; t public.tenancies; n uuid; r numeric; BEGIN SELECT * INTO c FROM public.rent_charges WHERE id=_charge FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Cargo no disponible'; END IF; SELECT * INTO t FROM public.tenancies WHERE id=c.tenancy_id; IF NOT public.contract_party(t.id) THEN RAISE EXCEPTION 'Sin permiso'; END IF; IF _amount<=0 OR _method NOT IN ('cash','transfer','check') OR length(coalesce(_note,''))>2000 THEN RAISE EXCEPTION 'Datos de pago inválidos'; END IF; r:=c.amount-c.credit_applied-coalesce((SELECT sum(amount) FROM public.payments WHERE charge_id=c.id AND confirmation_status='confirmed'),0); IF _amount>r THEN RAISE EXCEPTION 'El pago supera el saldo'; END IF; IF auth.uid()=t.tenant_id AND (_proof IS NULL OR split_part(_proof,'/',1)<>t.id::text OR split_part(_proof,'/',2)<>auth.uid()::text) THEN RAISE EXCEPTION 'Adjunta un comprobante'; END IF; INSERT INTO public.payments(landlord_id,property_id,tenant_id,category,kind,method,amount,paid_on,notes,charge_id,confirmation_status,proof_path) VALUES(t.landlord_id,t.property_id,t.tenant_id,'rent','income',_method,_amount,_paid_on,_note,c.id,CASE WHEN auth.uid()=t.landlord_id THEN 'confirmed' ELSE 'pending' END,_proof) RETURNING id INTO n; RETURN n; END; $$;
CREATE FUNCTION public.review_payment(_payment uuid,_approve boolean,_note text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.payments; c public.rent_charges; r numeric; BEGIN SELECT * INTO p FROM public.payments WHERE id=_payment FOR UPDATE; IF NOT FOUND OR p.landlord_id<>auth.uid() OR p.confirmation_status<>'pending' THEN RAISE EXCEPTION 'Comprobante no disponible'; END IF; IF length(coalesce(_note,''))>2000 OR (NOT _approve AND length(trim(coalesce(_note,'')))=0) THEN RAISE EXCEPTION 'Agrega una nota de rechazo'; END IF; SELECT * INTO c FROM public.rent_charges WHERE id=p.charge_id FOR UPDATE; r:=c.amount-c.credit_applied-coalesce((SELECT sum(amount) FROM public.payments WHERE charge_id=c.id AND confirmation_status='confirmed'),0); IF _approve AND p.amount>r THEN RAISE EXCEPTION 'El comprobante supera el saldo actual'; END IF; UPDATE public.payments SET confirmation_status=CASE WHEN _approve THEN 'confirmed' ELSE 'rejected' END,review_note=_note WHERE id=p.id; END; $$;
CREATE POLICY "Confirmed manual records only" ON public.payments AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(confirmation_status='confirmed' AND proof_path IS NULL AND charge_id IS NULL AND amount>0);
CREATE POLICY "No direct proof changes" ON public.payments AS RESTRICTIVE FOR UPDATE TO authenticated USING(charge_id IS NULL) WITH CHECK(charge_id IS NULL AND confirmation_status='confirmed');
CREATE POLICY "No delete receipted payments" ON public.payments AS RESTRICTIVE FOR DELETE TO authenticated USING(charge_id IS NULL);
CREATE FUNCTION public.rental_event_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; target uuid; label text; link text; BEGIN IF TG_TABLE_NAME='rent_charges' THEN tid:=NEW.tenancy_id; label:='Cargo generado'; link:='/payments'; ELSIF TG_TABLE_NAME='messages' THEN tid:=NEW.tenancy_id; target:=NEW.recipient_id; label:='Mensaje nuevo'; link:='/messages?contract='||tid; ELSIF TG_TABLE_NAME='issues' THEN tid:=NEW.tenancy_id; target:=CASE WHEN TG_OP='INSERT' THEN NEW.landlord_id ELSE NEW.tenant_id END; label:=CASE WHEN TG_OP='INSERT' THEN 'Reparación reportada' ELSE 'Reparación actualizada' END; link:='/issues'; ELSIF TG_TABLE_NAME='payments' THEN SELECT tenancy_id INTO tid FROM public.rent_charges WHERE id=NEW.charge_id; target:=CASE WHEN NEW.confirmation_status='pending' THEN NEW.landlord_id ELSE NEW.tenant_id END; label:=CASE NEW.confirmation_status WHEN 'pending' THEN 'Comprobante por confirmar' WHEN 'rejected' THEN 'Comprobante rechazado' ELSE 'Pago confirmado' END; link:='/payments'; ELSE tid:=NEW.tenancy_id; label:=CASE TG_TABLE_NAME WHEN 'contract_documents' THEN 'Documento agregado' WHEN 'rental_expenses' THEN 'Gasto registrado' ELSE 'Inventario registrado' END; link:='/contracts'; END IF; IF tid IS NOT NULL THEN INSERT INTO public.activity_log(tenancy_id,event,reference_id,actor_id) VALUES(tid,label,NEW.id,auth.uid()); END IF; IF target IS NOT NULL THEN INSERT INTO public.notifications(user_id,title,path,reference_id) VALUES(target,label,link,NEW.id); END IF; RETURN NEW; END; $$;
CREATE TRIGGER charges_activity AFTER INSERT ON public.rent_charges FOR EACH ROW EXECUTE FUNCTION public.rental_event_trigger();
CREATE TRIGGER messages_activity AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.rental_event_trigger();
CREATE TRIGGER issues_activity AFTER INSERT OR UPDATE OF status ON public.issues FOR EACH ROW EXECUTE FUNCTION public.rental_event_trigger();
CREATE TRIGGER payments_activity AFTER INSERT OR UPDATE OF confirmation_status ON public.payments FOR EACH ROW EXECUTE FUNCTION public.rental_event_trigger();
CREATE TRIGGER documents_activity AFTER INSERT ON public.contract_documents FOR EACH ROW EXECUTE FUNCTION public.rental_event_trigger();
CREATE TRIGGER expenses_activity AFTER INSERT ON public.rental_expenses FOR EACH ROW EXECUTE FUNCTION public.rental_event_trigger();
CREATE FUNCTION public.resolve_repair(_issue uuid,_cost numeric,_months integer DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.issues; BEGIN SELECT * INTO i FROM public.issues WHERE id=_issue FOR UPDATE; IF NOT FOUND OR i.landlord_id<>auth.uid() THEN RAISE EXCEPTION 'Sin permiso'; END IF; IF i.status='resolved' THEN RETURN; END IF; IF _cost<0 OR (_months IS NOT NULL AND _months NOT BETWEEN 1 AND 120) THEN RAISE EXCEPTION 'Costo o periodicidad inválidos'; END IF; IF i.tenancy_id IS NOT NULL AND _cost>0 THEN INSERT INTO public.rental_expenses(tenancy_id,property_id,category,amount,payer,reimbursement,issue_id,note) VALUES(i.tenancy_id,i.property_id,'repair',_cost,CASE WHEN i.payer='landlord' THEN 'landlord' ELSE 'tenant' END,CASE WHEN i.payer='tenant_credit' THEN 'rent_credit' ELSE 'none' END,i.id,i.title) ON CONFLICT(issue_id) DO NOTHING; END IF; INSERT INTO public.maintenance_records(landlord_id,property_id,title,category,repaired_on,next_due_on,cost) VALUES(i.landlord_id,i.property_id,i.title,'maintenance',CURRENT_DATE,CASE WHEN _months IS NOT NULL THEN (CURRENT_DATE+make_interval(months=>_months))::date ELSE NULL END,_cost); UPDATE public.issues SET status='resolved',actual_cost=_cost WHERE id=i.id; END; $$;
CREATE POLICY "Upload contract files" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='contract-files' AND public.contract_party((storage.foldername(name))[1]::uuid) AND (storage.foldername(name))[2]=auth.uid()::text AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp','pdf','mp4','webm'));
CREATE POLICY "Read authorized contract files" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='contract-files' AND (public.contract_owner((storage.foldername(name))[1]::uuid) OR (EXISTS(SELECT 1 FROM public.contract_documents d WHERE d.path=name AND d.shared AND public.contract_party(d.tenancy_id))) OR (EXISTS(SELECT 1 FROM public.payments p JOIN public.rent_charges c ON c.id=p.charge_id WHERE p.proof_path=name AND public.contract_party(c.tenancy_id))) OR (EXISTS(SELECT 1 FROM public.inventories i WHERE i.photo_path=name AND public.contract_party(i.tenancy_id))) OR (EXISTS(SELECT 1 FROM public.issues i WHERE name=ANY(i.media_paths) AND i.tenant_id=auth.uid())) OR ((storage.foldername(name))[2]=auth.uid()::text AND public.contract_party((storage.foldername(name))[1]::uuid))));
CREATE OR REPLACE FUNCTION public.plan_property_limit(_plan text) RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE _plan WHEN 'free' THEN 1 WHEN 'basic' THEN 5 WHEN 'pro' THEN 1000000 WHEN 'premium' THEN 1000000 ELSE 1 END; $$;
CREATE OR REPLACE FUNCTION public.enforce_property_limit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p text; n integer; BEGIN PERFORM pg_advisory_xact_lock(hashtext(NEW.landlord_id::text)); SELECT plan INTO p FROM public.subscriptions WHERE user_id=NEW.landlord_id; SELECT count(*) INTO n FROM public.properties WHERE landlord_id=NEW.landlord_id; IF n>=public.plan_property_limit(p) THEN RAISE EXCEPTION 'Tu plan llegó al límite de propiedades. Consulta los planes.'; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,email,phone) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'full_name',''),200),coalesce(NEW.email,''),left(NEW.raw_user_meta_data->>'phone',40)); IF NEW.raw_user_meta_data->>'role'='landlord' THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'landlord'); INSERT INTO public.subscriptions(user_id,plan,status) VALUES(NEW.id,'free','active'); ELSE INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'tenant'); END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.contract_party(uuid),public.contract_owner(uuid),public.agree_inventory(uuid),public.generate_rent_charges(uuid),public.apply_rent_credits(uuid),public.record_charge_payment(uuid,numeric,text,date,text,text),public.review_payment(uuid,boolean,text),public.resolve_repair(uuid,numeric,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.contract_party(uuid),public.contract_owner(uuid),public.agree_inventory(uuid),public.generate_rent_charges(uuid),public.record_charge_payment(uuid,numeric,text,date,text,text),public.review_payment(uuid,boolean,text),public.resolve_repair(uuid,numeric,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.generate_rent_charges(uuid),public.apply_rent_credits(uuid) TO service_role;
CREATE INDEX charges_contract_due ON public.rent_charges(tenancy_id,due_on); CREATE INDEX notifications_recipient ON public.notifications(user_id,created_at); CREATE INDEX contract_activity ON public.activity_log(tenancy_id,created_at);